int Sum(ReadOnlySpan<byte> line)
{
    var total = 0;
    while (!line.IsEmpty)
    {
        var comma = line.IndexOf((byte)',');
        var field = comma < 0 ? line : line[..comma];
        Utf8Parser.TryParse(field, out int value, out _);
        total += value;
        line = comma < 0 ? default : line[(comma + 1)..];
    }
    return total;
}
